function searchMatrix(matrix, target) {
  let low = 0, high = matrix.length - 1;
  while (low < high) {                           // the last row starting at or below target
    const mid = low + Math.ceil((high - low) / 2);   // round up: low = mid must make progress
    if (matrix[mid][0] <= target) low = mid;
    else high = mid - 1;
  }
  const row = matrix[low];
  let l = 0, h = row.length - 1;
  while (l <= h) {                               // plain binary search in that row
    const mid = l + Math.floor((h - l) / 2);
    if (row[mid] === target) return true;
    if (row[mid] < target) l = mid + 1;
    else h = mid - 1;
  }
  return false;
}

